['Time loss (s)',f'{W["tl"]["1.28.0"].xs(2,level="p").mean():.2f}',f'{W["tl"]["1.20.0"].xs(2,level="p").mean():.2f}',f'{dtl.mean():+.2f} ({dtl.mean()-ci(dtl):+.2f}, {dtl.mean()+ci(dtl):+.2f})'],
